previewCss:
.darma-loader-darma-b13-bubble-wrap-pop { --accent: var(--loader-color, #38bdf8); --accent-2: var(--loader-secondary-color, #cbd5e1); width: var(--loader-size, 104px); height: var(--loader-size, 104px); display: grid; grid-template-columns: repeat(3, 1fr); gap: 5%; padding: 5%; border-radius: 9%; background: color-mix(in srgb, #fff 74%, var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 12%, var(--accent-2)); }
.darma-loader-darma-b13-bubble-wrap-pop span { border-radius: 50%; background: radial-gradient(circle at 34% 28%, rgba(255, 255, 255, .95), color-mix(in srgb, #fff 52%, var(--accent))); box-shadow: inset 0 calc(var(--loader-size, 104px) * -.015) calc(var(--loader-size, 104px) * .03) rgba(15, 23, 42, .18); animation: darma-loader-darma-b13-bubble-wrap-pop-deflate calc(var(--loader-speed, 1s) * 2.7) ease-in-out infinite; }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * 1.5); }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(6) { animation-delay: calc(var(--loader-speed, 1s) * 2.1); }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(7) { animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(8) { animation-delay: calc(var(--loader-speed, 1s) * 2.4); }
.darma-loader-darma-b13-bubble-wrap-pop span:nth-child(9) { animation-delay: calc(var(--loader-speed, 1s) * 1.8); }
@keyframes darma-loader-darma-b13-bubble-wrap-pop-deflate { 0%, 38% { transform: scale(1); } 44% { transform: scale(1.18); } 52% { transform: scale(.68); } 60%, 100% { transform: scale(1); } }

